<style>
*{box-sizing:border-box}.route-page{display:grid;gap:16px;min-width:0}.route-head{display:flex;justify-content:space-between;align-items:flex-start;gap:16px}.route-head h1{margin:0;font-size:clamp(24px,2vw,30px)}.route-head p{margin:5px 0 0}.route-actions{display:flex;gap:9px;flex-wrap:wrap}.route-stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.route-stat{min-height:112px;border-radius:14px;padding:18px;color:#fff;display:flex;align-items:center;gap:14px;overflow:hidden;position:relative}.route-stat:after{content:"";position:absolute;width:110px;height:110px;border-radius:50%;right:-35px;top:-40px;background:rgba(255,255,255,.1)}.route-stat.purple{background:linear-gradient(135deg,#7448e8,#4b36cf)}.route-stat.green{background:linear-gradient(135deg,#45c783,#1ea568)}.route-stat.orange{background:linear-gradient(135deg,#ffb327,#ff8a17)}.route-stat-icon{width:48px;height:48px;border-radius:50%;display:grid;place-items:center;background:rgba(255,255,255,.16);position:relative;z-index:1}.route-stat-icon svg{width:24px}.route-stat div{position:relative;z-index:1}.route-stat small{display:block;font-weight:700;font-size:11px}.route-stat strong{display:block;font-size:26px;margin-top:5px}.route-card{border-radius:14px;overflow:hidden;min-width:0}.route-card-head{padding:14px 16px;border-bottom:1px solid var(--border-soft,#e7ebf3);display:flex;justify-content:space-between;gap:10px}.route-filter{padding:14px 16px;display:grid;grid-template-columns:minmax(280px,1.5fr) minmax(170px,.6fr) auto;gap:10px;border-bottom:1px solid var(--border-soft,#e7ebf3)}.route-filter>*{min-height:40px}.route-table-wrap{overflow-x:auto;width:100%}.route-table{min-width:1320px;width:100%}.route-table th{white-space:nowrap;position:sticky;top:0;background:var(--card-bg,#fff);z-index:2;font-size:10px}.route-table td{font-size:11px;vertical-align:middle}.route-table th,.route-table td{padding:11px 10px}.route-row{cursor:pointer}.route-row:hover{background:rgba(79,70,229,.035)}.route-link{display:flex;align-items:center;gap:8px;color:inherit;text-decoration:none}.route-link-icon{width:31px;height:31px;border-radius:8px;display:grid;place-items:center;background:#eef2ff;color:#4f46e5;flex:0 0 auto}.route-link-icon svg{width:15px}.route-badge{display:inline-flex;padding:5px 9px;border-radius:999px;font-size:9px;font-weight:800;text-transform:capitalize}.route-badge.active{color:#16834f;background:#e8f8ef}.route-badge.inactive{color:#dc2626;background:#fff0f1}.stops-badge{display:inline-flex;align-items:center;gap:5px;padding:5px 9px;border-radius:999px;background:#eef2ff;color:#4338ca;font-size:9px;font-weight:800}.route-action-group{display:flex;gap:5px}.route-action{width:31px;height:31px;border:1px solid #d7def1;border-radius:7px;background:var(--card-bg,#fff);display:grid;place-items:center;color:#4f46e5}.route-action.edit{color:#2563eb}.route-action.delete{color:#dc2626}.route-action svg{width:14px}.route-empty{text-align:center!important;padding:40px 15px!important}.route-foot{padding:12px 16px;border-top:1px solid var(--border-soft,#e7ebf3);display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap}.route-form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.route-view-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.route-view-item{padding:12px;border:1px solid var(--border-soft,#e3e8f1);border-radius:10px;background:rgba(99,102,241,.035)}.route-view-item small{display:block;font-size:9px;font-weight:700;color:var(--text-muted,#64748b)}.route-view-item strong{display:block;margin-top:5px;overflow-wrap:anywhere}.route-toast{position:fixed;right:18px;top:18px;z-index:2200;width:min(390px,calc(100vw - 36px));padding:13px 15px;border-radius:10px;color:#fff;box-shadow:0 18px 40px rgba(15,23,42,.18);opacity:0;visibility:hidden;transform:translateY(-8px);transition:.2s;font-size:12px;font-weight:700}.route-toast.show{opacity:1;visibility:visible;transform:translateY(0)}.route-toast.success{background:#16834f}.route-toast.error{background:#dc2626}#routeModal .modal-dialog{width:min(980px,calc(100vw - 32px));max-width:980px}#routeModal .modal-content,#viewRouteModal .modal-content,#deleteRouteModal .modal-content{max-height:calc(100dvh - 32px);overflow:hidden}#routeModal form{display:flex;flex-direction:column;max-height:calc(100dvh - 32px)}#routeModal .modal-body,#viewRouteModal .modal-body,#deleteRouteModal .modal-body{overflow-y:auto}.driver-readonly{background:rgba(100,116,139,.06)!important}@media(max-width:1199px){.route-head{flex-direction:column}.route-stats{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:767px){.route-actions{display:grid;grid-template-columns:1fr 1fr;width:100%}.route-actions .btn-ui{justify-content:center}.route-stats{grid-template-columns:1fr}.route-filter,.route-form-grid,.route-view-grid{grid-template-columns:1fr}.route-table{min-width:1150px}}@media(max-width:575px){#routeModal .modal-dialog,#viewRouteModal .modal-dialog,#deleteRouteModal .modal-dialog{width:calc(100vw - 16px);margin:8px auto}.modal-footer{display:grid;grid-template-columns:1fr}.modal-footer .btn-ui{width:100%;justify-content:center}}
</style>
<div id="routeToast" class="route-toast" role="status" aria-live="polite"></div>
<div class="route-page">
 <div class="route-head">
  <div><h1>Route Master</h1><p class="text-muted">Manage routes, vehicles, drivers and stops.</p></div>
  <div class="route-actions">
   <button id="addRouteBtn" class="btn-ui btn-primary-ui" type="button"><i data-lucide="plus"></i> Add Route</button>
   <button id="refreshRouteBtn" class="btn-ui" type="button"><i data-lucide="refresh-cw"></i> Refresh</button>
  </div>
 </div>
 <section class="route-stats">
  <article class="route-stat purple"><span class="route-stat-icon"><i data-lucide="route"></i></span><div><small>Total Routes</small><strong id="statTotal">0</strong></div></article>
  <article class="route-stat green"><span class="route-stat-icon"><i data-lucide="circle-check-big"></i></span><div><small>Active Routes</small><strong id="statActive">0</strong></div></article>
  <article class="route-stat orange"><span class="route-stat-icon"><i data-lucide="circle-pause"></i></span><div><small>Inactive Routes</small><strong id="statInactive">0</strong></div></article>
 </section>
 <section class="ui-card route-card">
  <div class="route-card-head"><strong>Route List</strong><small id="routeListCount" class="text-muted">Loading...</small></div>
  <div class="route-filter">
   <input id="routeSearch" class="form-control" type="search" placeholder="Search by Route Name" autocomplete="off">
   <select id="routeStatusFilter" class="form-select"><option value="all">All Statuses</option><option value="active">Active</option><option value="inactive">Inactive</option></select>
   <button id="resetRouteFiltersBtn" class="btn-ui" type="button"><i data-lucide="rotate-ccw"></i> Reset</button>
  </div>
  <div class="route-table-wrap">
   <table class="data-table route-table">
    <thead><tr><th>#</th><th>Route Name</th><th>Route Code</th><th>Zone / Area</th><th>Start Location</th><th>End Location</th><th>Assigned Vehicle</th><th>Assigned Driver</th><th>Stops</th><th>Status</th><th>Actions</th></tr></thead>
    <tbody id="routeTableBody"><tr><td colspan="11" class="route-empty">Loading routes...</td></tr></tbody>
   </table>
  </div>
  <div class="route-foot"><small id="routeRecordInfo" class="text-muted">0 routes</small><small class="text-muted">Click a route to manage its stops.</small></div>
 </section>
</div>

<div class="modal fade" id="routeModal" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-xl modal-dialog-centered"><div class="modal-content"><form id="routeForm" novalidate>
 <div class="modal-header"><div><h5 id="routeModalTitle" class="modal-title">Add Route</h5><small id="routeModalSubtitle" class="text-muted">Enter the route information.</small></div><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button></div>
 <div class="modal-body route-form-grid">
  <input id="routeId" type="hidden">
  <div><label class="form-label" for="routeName">Route Name *</label><input id="routeName" class="form-control" maxlength="150" placeholder="Example: Town Main Route" required></div>
  <div><label class="form-label" for="routeCode">Route Code *</label><input id="routeCode" class="form-control" maxlength="50" placeholder="Example: RT-001" required></div>
  <div><label class="form-label" for="zoneArea">Zone / Area *</label><input id="zoneArea" class="form-control" maxlength="150" placeholder="Example: North Zone" required></div>
  <div><label class="form-label" for="startPoint">Start Location *</label><input id="startPoint" class="form-control" maxlength="150" placeholder="Enter start location" required></div>
  <div><label class="form-label" for="endPoint">End Location *</label><input id="endPoint" class="form-control" maxlength="150" placeholder="Enter end location" required></div>
  <div><label class="form-label" for="vehicleId">Assigned Vehicle *</label><select id="vehicleId" class="form-select" required><option value="">Select vehicle</option></select></div>
  <div><label class="form-label" for="driverName">Assigned Driver</label><input id="driverName" class="form-control driver-readonly" readonly placeholder="Auto loaded from Vehicle Master"></div>
  <div><label class="form-label" for="routeStatus">Status *</label><select id="routeStatus" class="form-select" required><option value="active">Active</option><option value="inactive">Inactive</option></select></div>
 </div>
 <div class="modal-footer"><button id="deleteRouteFromFormBtn" type="button" class="btn-ui" hidden><i data-lucide="trash-2"></i> Delete</button><button id="resetRouteFormBtn" type="button" class="btn-ui"><i data-lucide="rotate-ccw"></i> Reset</button><button type="button" class="btn-ui" data-bs-dismiss="modal">Cancel</button><button id="saveRouteBtn" type="submit" class="btn-ui btn-primary-ui"><i data-lucide="save"></i><span id="saveRouteBtnText">Add Route</span></button></div>
</form></div></div></div>

<div class="modal fade" id="viewRouteModal" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-lg modal-dialog-centered"><div class="modal-content"><div class="modal-header"><div><h5 class="modal-title">Route Details</h5><small id="viewRouteSubtitle" class="text-muted"></small></div><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div id="viewRouteContent" class="route-view-grid"></div></div><div class="modal-footer"><button id="openStopsFromViewBtn" type="button" class="btn-ui btn-primary-ui"><i data-lucide="map-pinned"></i> Route Stops</button><button type="button" class="btn-ui" data-bs-dismiss="modal">Close</button></div></div></div></div>

<div class="modal fade" id="deleteRouteModal" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><div class="modal-header"><div><h5 class="modal-title">Delete Route</h5><small class="text-muted">This also deletes its stops.</small></div><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><p>Are you sure you want to delete this route?</p><div class="alert alert-warning mb-0"><strong id="deleteRouteLabel">-</strong></div></div><div class="modal-footer"><button type="button" class="btn-ui" data-bs-dismiss="modal">Cancel</button><button id="confirmDeleteRouteBtn" type="button" class="btn-ui btn-primary-ui"><i data-lucide="trash-2"></i> Delete Route</button></div></div></div></div>

<script>
(function(){
 'use strict';
 const apiUrl=new URL('../api/route-management.php',window.location.href).href;
 let csrfToken=<?=json_encode($routeCsrf)?>,routes=[],vehicles=[],deleteRouteId=0,viewRouteId=0,searchTimer=null,toastTimer=null;
 const $=id=>document.getElementById(id);
 const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
 function toast(message,success){const el=$('routeToast');el.className='route-toast show '+(success?'success':'error');el.textContent=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='route-toast',5000)}
 async function request(action,data={},method='GET'){
  let response;
  if(method==='GET'){const url=new URL(apiUrl);url.searchParams.set('action',action);Object.keys(data).forEach(key=>{if(data[key]!==''&&data[key]!==null&&data[key]!==undefined)url.searchParams.set(key,String(data[key]))});response=await fetch(url,{credentials:'same-origin',headers:{Accept:'application/json'}})}
  else response=await fetch(apiUrl,{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','Content-Type':'application/json'},body:JSON.stringify(Object.assign({action,csrf_token:csrfToken},data))});
  const text=await response.text();let result;try{result=JSON.parse(text)}catch(e){throw new Error('Route API returned HTTP '+response.status+'. '+(text.replace(/\s+/g,' ').trim().slice(0,220)||'Invalid server response.'))}if(!response.ok||!result.success)throw new Error(result.message||'Route request failed.');if(result.data?.csrf_token)csrfToken=result.data.csrf_token;return result;
 }
 const statusBadge=status=>'<span class="route-badge '+esc(String(status||'inactive').toLowerCase())+'">'+esc(status||'inactive')+'</span>';
 const stopsUrl=id=>'route-stops.php?route_id='+encodeURIComponent(id);
 function setVehicleOptions(records,selectedId=0){vehicles=Array.isArray(records)?records:[];$('vehicleId').innerHTML='<option value="">Select vehicle</option>'+vehicles.map(v=>{const inactive=String(v.status).toLowerCase()!=='active';return '<option value="'+Number(v.id)+'" '+(inactive?'disabled':'')+'>'+esc(v.vehicle_name+' • '+v.vehicle_number+(inactive?' (Inactive)':''))+'</option>'}).join('');if(selectedId>0)$('vehicleId').value=String(selectedId);updateDriver()}
 function updateDriver(){const id=Number($('vehicleId').value||0),vehicle=vehicles.find(v=>Number(v.id)===id);$('driverName').value=vehicle?(vehicle.driver_name||'Not Assigned'):''}
 function updateStats(stats={}){$('statTotal').textContent=Number(stats.total_routes||0);$('statActive').textContent=Number(stats.active_routes||0);$('statInactive').textContent=Number(stats.inactive_routes||0)}
 function render(records){routes=records||[];$('routeListCount').textContent=routes.length+' route'+(routes.length===1?'':'s');$('routeRecordInfo').textContent=routes.length+' route'+(routes.length===1?'':'s')+' displayed';$('routeTableBody').innerHTML=routes.map((r,i)=>'<tr class="route-row" data-id="'+Number(r.id)+'"><td>'+(i+1)+'</td><td><a class="route-link js-open-stops" href="'+stopsUrl(r.id)+'"><span class="route-link-icon"><i data-lucide="route"></i></span><strong>'+esc(r.route_name)+'</strong></a></td><td><strong>'+esc(r.route_code)+'</strong></td><td>'+esc(r.zone_area)+'</td><td>'+esc(r.start_point)+'</td><td>'+esc(r.end_point)+'</td><td>'+esc(r.vehicle_name?r.vehicle_name+' • '+r.vehicle_number:'Not Assigned')+'</td><td>'+esc(r.driver_name||'Not Assigned')+'</td><td><span class="stops-badge"><i data-lucide="map-pin"></i>'+Number(r.stop_count||0)+'</span></td><td>'+statusBadge(r.status)+'</td><td><div class="route-action-group"><button class="route-action js-view" data-id="'+Number(r.id)+'" title="View"><i data-lucide="eye"></i></button><button class="route-action js-stops" data-id="'+Number(r.id)+'" title="Route Stops"><i data-lucide="map-pinned"></i></button><button class="route-action edit js-edit" data-id="'+Number(r.id)+'" title="Edit"><i data-lucide="pencil"></i></button><button class="route-action delete js-delete" data-id="'+Number(r.id)+'" title="Delete"><i data-lucide="trash-2"></i></button></div></td></tr>').join('')||'<tr><td colspan="11" class="route-empty">No routes found.</td></tr>';
  document.querySelectorAll('.route-row').forEach(row=>row.addEventListener('click',e=>{if(e.target.closest('button,a'))return;location.href=stopsUrl(row.dataset.id)}));
  document.querySelectorAll('.js-view').forEach(b=>b.onclick=e=>{e.stopPropagation();viewRoute(Number(b.dataset.id))});document.querySelectorAll('.js-stops').forEach(b=>b.onclick=e=>{e.stopPropagation();location.href=stopsUrl(b.dataset.id)});document.querySelectorAll('.js-edit').forEach(b=>b.onclick=e=>{e.stopPropagation();openForm(Number(b.dataset.id))});document.querySelectorAll('.js-delete').forEach(b=>b.onclick=e=>{e.stopPropagation();openDelete(Number(b.dataset.id))});if(window.lucide)lucide.createIcons();
 }
 async function load(){try{const result=await request('list',{search:$('routeSearch').value.trim(),status:$('routeStatusFilter').value});setVehicleOptions(result.data.vehicles||vehicles,0);render(result.data.records||[]);updateStats(result.data.stats||{})}catch(e){$('routeTableBody').innerHTML='<tr><td colspan="11" class="route-empty">'+esc(e.message)+'</td></tr>';toast(e.message,false)}}
 function clearForm(){$('routeForm').reset();$('routeId').value='';$('routeStatus').value='active';$('driverName').value='';$('routeModalTitle').textContent='Add Route';$('routeModalSubtitle').textContent='Enter the route information.';$('saveRouteBtnText').textContent='Add Route';$('deleteRouteFromFormBtn').hidden=true}
 function fill(r){$('routeId').value=r.id;$('routeName').value=r.route_name||'';$('routeCode').value=r.route_code||'';$('zoneArea').value=r.zone_area||'';$('startPoint').value=r.start_point||'';$('endPoint').value=r.end_point||'';setVehicleOptions(vehicles,Number(r.vehicle_id||0));$('driverName').value=r.driver_name||'Not Assigned';$('routeStatus').value=String(r.status||'active').toLowerCase();$('routeModalTitle').textContent='Update Route';$('routeModalSubtitle').textContent=(r.route_code||'')+' • '+(r.route_name||'');$('saveRouteBtnText').textContent='Update Route';$('deleteRouteFromFormBtn').hidden=false}
 async function openForm(id=0){clearForm();if(!vehicles.length){try{const result=await request('vehicles');setVehicleOptions(result.data.vehicles||[],0)}catch(e){toast(e.message,false)}}if(id>0){try{const result=await request('detail',{id});setVehicleOptions(result.data.vehicles||vehicles,Number(result.data.record.vehicle_id||0));fill(result.data.record)}catch(e){toast(e.message,false);return}}bootstrap.Modal.getOrCreateInstance($('routeModal')).show();setTimeout(()=>$('routeName').focus(),250);if(window.lucide)lucide.createIcons()}
 function validate(){const data={id:Number($('routeId').value||0),route_name:$('routeName').value.trim(),route_code:$('routeCode').value.trim().toUpperCase(),zone_area:$('zoneArea').value.trim(),start_point:$('startPoint').value.trim(),end_point:$('endPoint').value.trim(),vehicle_id:Number($('vehicleId').value||0),status:$('routeStatus').value};if(!data.route_name)throw new Error('Route Name is required.');if(!data.route_code)throw new Error('Route Code is required.');if(!data.zone_area)throw new Error('Zone / Area is required.');if(!data.start_point)throw new Error('Start Location is required.');if(!data.end_point)throw new Error('End Location is required.');if(data.vehicle_id<=0)throw new Error('Assigned Vehicle is required.');return data}
 async function save(e){e.preventDefault();let data;try{data=validate()}catch(err){toast(err.message,false);return}const btn=$('saveRouteBtn');btn.disabled=true;try{const result=await request('save',data,'POST');bootstrap.Modal.getInstance($('routeModal'))?.hide();toast(result.message,true);await load()}catch(err){toast(err.message,false)}finally{btn.disabled=false}}
 async function viewRoute(id){try{const result=await request('detail',{id}),r=result.data.record;viewRouteId=id;$('viewRouteSubtitle').textContent=r.route_code+' • '+r.route_name;const fields=[['Route Name',r.route_name],['Route Code',r.route_code],['Zone / Area',r.zone_area],['Start Location',r.start_point],['End Location',r.end_point],['Assigned Vehicle',r.vehicle_name?r.vehicle_name+' • '+r.vehicle_number:'Not Assigned'],['Assigned Driver',r.driver_name||'Not Assigned'],['Total Stops',r.stop_count||0],['Status',String(r.status||'').toUpperCase()],['Created At',r.created_at_display||'-']];$('viewRouteContent').innerHTML=fields.map(f=>'<div class="route-view-item"><small>'+esc(f[0])+'</small><strong>'+esc(f[1])+'</strong></div>').join('');bootstrap.Modal.getOrCreateInstance($('viewRouteModal')).show();if(window.lucide)lucide.createIcons()}catch(e){toast(e.message,false)}}
 function openDelete(id){deleteRouteId=id;const r=routes.find(x=>Number(x.id)===id);$('deleteRouteLabel').textContent=r?r.route_code+' • '+r.route_name:'Selected route';bootstrap.Modal.getOrCreateInstance($('deleteRouteModal')).show();if(window.lucide)lucide.createIcons()}
 async function remove(){if(deleteRouteId<=0)return;const btn=$('confirmDeleteRouteBtn');btn.disabled=true;try{const result=await request('delete',{id:deleteRouteId},'POST');bootstrap.Modal.getInstance($('deleteRouteModal'))?.hide();bootstrap.Modal.getInstance($('routeModal'))?.hide();toast(result.message,true);deleteRouteId=0;await load()}catch(e){toast(e.message,false)}finally{btn.disabled=false}}
 $('addRouteBtn').onclick=()=>openForm(0);$('refreshRouteBtn').onclick=load;$('vehicleId').onchange=updateDriver;$('routeCode').oninput=function(){this.value=this.value.toUpperCase()};$('routeForm').onsubmit=save;$('confirmDeleteRouteBtn').onclick=remove;$('deleteRouteFromFormBtn').onclick=()=>openDelete(Number($('routeId').value||0));$('openStopsFromViewBtn').onclick=()=>{if(viewRouteId>0)location.href=stopsUrl(viewRouteId)};$('resetRouteFormBtn').onclick=()=>{const id=Number($('routeId').value||0);id?openForm(id):clearForm()};$('routeStatusFilter').onchange=load;$('routeSearch').oninput=()=>{clearTimeout(searchTimer);searchTimer=setTimeout(load,300)};$('resetRouteFiltersBtn').onclick=()=>{$('routeSearch').value='';$('routeStatusFilter').value='all';load()};load();if(window.lucide)lucide.createIcons();
})();
</script>
<?php require dirname(__DIR__) . '/includes/layout-end.php'; ?>
